/** The built-in rule pack's TOML, exactly as the file holds it. */
export const BUILTIN_PACK_TOML: string =
  '# The built-in redaction rule pack (F2.1). Every seshi server and client runs it, before or after\n# the operator\'s own packs ([redaction] packs). An operator pack can turn a rule off by its id\n# (disable = ["entropy"]) but cannot change it.\n#\n# Rules marked implementation = "builtin" are matched by reviewed code\n# (packages/ts/redact/src/secrets.ts) in JavaScript regular expressions; F2.2 allows that for\n# built-in rules. This file names them, says what each catches, and holds test strings that\n# packages/ts/redact tests run against the code. The sensitive-file globs and secret commands\n# below are data: what is listed here is what runs.\n#\n# After editing, run `bun run packs` (it regenerates src/generated/builtin-pack.ts) and bump\n# `version` whenever what the rules match changes, so metadata.redaction.rule_set tells sessions\n# redacted before the change from those after.\n#\n# Some test strings spell a token\'s first character as a \\u escape, so the file holds no string\n# that secret scanners take for a real credential.\n\nid = "builtin"\nversion = "seshi/rules/3"\ndescription = "Secrets in the shapes credentials take, files that hold secrets, and commands that print them."\n\n# --- Text rules, in the order they run (after the operator\'s text rules). ---\n\n[[rules]]\nid = "private-key"\ndescription = "PEM private key blocks, delimiters included."\nimplementation = "builtin"\ntests.match = ["-----BEGIN RSA PRIVATE KEY-----\\nMIIEowIBAAKCAQEA0Zx0FAKE\\n-----END RSA PRIVATE KEY-----"]\ntests.no_match = ["-----BEGIN CERTIFICATE-----\\nMIIB\\n-----END CERTIFICATE-----"]\n\n[[rules]]\nid = "url-credentials"\ndescription = "The password in a URL\'s user:password@host; the user and host are kept."\nimplementation = "builtin"\ntests.match = ["DATABASE_URL is postgres://admin:s3cr3t@db.internal:5432/app"]\ntests.no_match = ["https://example.com/docs:intro"]\n\n[[rules]]\nid = "aws-secret"\ndescription = "An AWS secret access key assigned to its variable."\nimplementation = "builtin"\ntests.match = ["AWS_SECRET_ACCESS_KEY=wJalrXUtnFEMIK7MDENGbPxRfiCYEXAMPLEKEY00"]\ntests.no_match = ["aws configure list"]\n\n[[rules]]\nid = "seshi-token"\ndescription = "seshi\'s own opaque tokens (seshi_<id>_<secret>)."\nimplementation = "builtin"\ntests.match = ["my token is seshi_0123456789abcdef0123_aB3_-aB3_-aB3_-aB3_-aB3_-aB3_-aB3_-aB3_-xY- ok"]\ntests.no_match = ["seshi_status is fine"]\n\n[[rules]]\nid = "aws-access-key"\ndescription = "AWS access key ids (AKIA…, ASIA…)."\nimplementation = "builtin"\ntests.match = ["creds AKIAIOSFODNN7EXAMPLE end"]\ntests.no_match = ["AKIA is a prefix"]\n\n[[rules]]\nid = "quoted-secret"\ndescription = "A password, secret, token or API key named in prose and quoted."\nimplementation = "builtin"\ntests.match = [\'FATAL: password authentication failed with password "S3cr3tP@ssw0rd!"\']\ntests.no_match = ["the password rules require 8 characters"]\n\n[[rules]]\nid = "bearer-token"\ndescription = "The token after Bearer or Basic; the scheme is kept."\nimplementation = "builtin"\ntests.match = ["Authorization: Bearer abc.def-ghi_jkl~mno123456"]\ntests.no_match = ["a bearer of bad news"]\n\n[[rules]]\nid = "jwt"\ndescription = "JSON Web Tokens, including ones glued to a preceding word character."\nimplementation = "builtin"\ntests.match = ["anon key eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiIxIn0.abc123def456ghi"]\ntests.no_match = ["keyJsonSchema.properties.name"]\n\n[[rules]]\nid = "credential"\ndescription = "A value assigned to a key that names a credential (api_key, *_TOKEN, password, …, in several languages), or shown on the line under such a label."\nimplementation = "builtin"\ntests.match = [\n  "export DATABASE_PASSWORD=hunter2hunter2hunter2",\n  \'{"api_key": "abcd1234efgh5678ijkl"}\',\n  "пароль: abcd1234efgh5678ijkl",\n]\ntests.no_match = ["cache_key: build-artifacts-v2", "the token count was 42"]\n\n[[rules]]\nid = "github-token"\ndescription = "GitHub tokens: ghp_, gho_, ghs_, ghu_, ghr_ and github_pat_."\nimplementation = "builtin"\ntests.match = ["push with \\u0067hp_abcdefghijklmnopqrstuvwx0123456789"]\ntests.no_match = ["ghp_short"]\n\n[[rules]]\nid = "gitlab-token"\ndescription = "GitLab personal access tokens (glpat-)."\nimplementation = "builtin"\ntests.match = ["ci \\u0067lpat-abcdefghij0123456789"]\n\n[[rules]]\nid = "stripe-key"\ndescription = "Stripe secret and restricted keys (sk_live_, sk_test_, rk_live_, rk_test_)."\nimplementation = "builtin"\ntests.match = ["stripe \\u0073k_live_abcdefghijklmnop"]\n\n[[rules]]\nid = "user-key"\ndescription = "Per-user keys shaped sk_user_…."\nimplementation = "builtin"\ntests.match = ["key \\u0073k_user_abcdef1234567890"]\n\n[[rules]]\nid = "anthropic-key"\ndescription = "Anthropic API keys (sk-ant-)."\nimplementation = "builtin"\ntests.match = ["llm \\u0073k-ant-api03-abcdefghijklmnopqrstuvwxyz"]\n\n[[rules]]\nid = "openai-key"\ndescription = "OpenAI-style keys (sk-, sk-proj-)."\nimplementation = "builtin"\ntests.match = ["openai \\u0073k-proj-abcdefghijklmnopqrstuvwxyz"]\ntests.no_match = ["sk-learn is a library"]\n\n[[rules]]\nid = "groq-key"\ndescription = "Groq API keys (gsk_)."\nimplementation = "builtin"\ntests.match = ["groq \\u0067sk_abcdefghijklmnopqrstuvwxyz"]\n\n[[rules]]\nid = "xai-key"\ndescription = "xAI API keys (xai-)."\nimplementation = "builtin"\ntests.match = ["xai \\u0078ai-abcdefghijklmnopqrstuvwxyz"]\n\n[[rules]]\nid = "huggingface-token"\ndescription = "Hugging Face tokens (hf_)."\nimplementation = "builtin"\ntests.match = ["hf \\u0068f_abcdefghijklmnopqrstuvwxyz"]\n\n[[rules]]\nid = "npm-token"\ndescription = "npm access tokens (npm_)."\nimplementation = "builtin"\ntests.match = ["publish \\u006epm_abcdefghijklmnopqrstuvwxyz0123456789"]\n\n[[rules]]\nid = "slack-token"\ndescription = "Slack tokens (xoxb-, xoxp-, xoxc-, xoxs-)."\nimplementation = "builtin"\ntests.match = ["hook \\u0078oxb-1234567890-abcdefghij"]\n\n[[rules]]\nid = "google-api-key"\ndescription = "Google API keys (AIza…)."\nimplementation = "builtin"\ntests.match = ["maps \\u0041IzaSyA1234567890abcdefghijklmnopqrstuv"]\n\n[[rules]]\nid = "pulumi-token"\ndescription = "Pulumi access tokens (pul- and 40 hex digits)."\nimplementation = "builtin"\ntests.match = ["login \\u0070ul-0123456789abcdef0123456789abcdef01234567"]\n\n[[rules]]\nid = "supabase-token"\ndescription = "Supabase access tokens (sbp_ and 40 hex digits)."\nimplementation = "builtin"\ntests.match = ["deploy \\u0073bp_0123456789abcdef0123456789abcdef01234567"]\n\n[[rules]]\nid = "provider-token"\ndescription = "Any other provider token shape the provider pattern finds (a fallback name)."\nimplementation = "builtin"\n\n[[rules]]\nid = "entropy"\ndescription = "A long high-entropy string where a secret would sit: the value of an assignment, or alone on its line. Hex, paths and lowercase-only words are left alone."\nimplementation = "builtin"\ntests.match = ["DEPLOY_CRED=aB3xY7pQ9zK2mN8vR4tWcD5f", "paste:\\n  aB3xY7pQ9zK2mN8vR4tWcD5fGh6J\\ndone"]\ntests.no_match = ["commit d3b07384d113edec49eaa6238ad5ff00d3b07384", "moved to: aB3xY7pQ9zK2mN8vR4tWcD5f"]\n\n# --- Sensitive files: a tool call that names one keeps its call, and its result is withheld. ---\n\n[[sensitive_files]]\nid = "sensitive-file"\ndescription = "Files that hold secrets in nearly every project and machine."\nglobs = [\n  ".env",\n  ".env.*",\n  "!.env.example",\n  "!.env.sample",\n  "!.env.template",\n  "!.env.dist",\n  "*.pem",\n  "*.key",\n  "*.p12",\n  "*.pfx",\n  "*.keystore",\n  "*.jks",\n  "id_rsa",\n  "id_dsa",\n  "id_ecdsa",\n  "id_ed25519",\n  ".netrc",\n  "_netrc",\n  ".pgpass",\n  ".npmrc",\n  ".pypirc",\n  ".git-credentials",\n  ".dockercfg",\n  ".docker/config.json",\n  ".aws/credentials",\n  ".azure/accessTokens.json",\n  ".config/gcloud/**/*credentials*.json",\n  "application_default_credentials.json",\n  "service-account*.json",\n  ".kube/config",\n  "*.tfvars",\n  "*.tfstate",\n  "secrets.yml",\n  "secrets.yaml",\n  ".vault-token",\n]\ntests.match = [".env", "app/.env.local", "/home/a/.aws/credentials", "deploy/prod.tfvars"]\ntests.no_match = [".env.example", "src/env.ts", "README.md"]\n\n# --- Secret commands: a tool call that runs one keeps its call, and its output is withheld. ---\n\n[[secret_commands]]\nid = "secret-output"\ndescription = "Commands whose output is a secret, or the environment that holds them."\npatterns = [\n  \'printenv\\b\',\n  \'env(?:\\s+-0)?\\s*$\',\n  \'set\\s*$\',\n  \'export\\s+-p\\s*$\',\n  \'gh\\s+auth\\s+token\\b\',\n  \'(?:gh|glab)\\s+auth\\s+status\\b.*(?:--show-token|\\s-t\\b)\',\n  \'git\\s+credential\\s+fill\\b\',\n  \'aws\\s+configure\\s+(?:get|export-credentials)\\b\',\n  \'aws\\s+sts\\s+(?:get-session-token|get-federation-token|assume-role\\S*)\\b\',\n  \'aws\\s+ecr(?:-public)?\\s+get-login-password\\b\',\n  \'aws\\s+secretsmanager\\s+get-secret-value\\b\',\n  \'aws\\s+ssm\\s+get-parameters?(?:-by-path)?\\b.*--with-decryption\',\n  \'gcloud\\s+auth\\s+(?:application-default\\s+)?print-(?:access|identity)-token\\b\',\n  \'gcloud\\s+secrets\\s+versions\\s+access\\b\',\n  \'az\\s+(?:account\\s+get-access-token|keyvault\\s+secret\\s+show)\\b\',\n  \'kubectl\\s+get\\s+secrets?\\b\',\n  \'kubectl\\s+config\\s+view\\b.*--raw\',\n  \'vault\\s+(?:kv\\s+get|read|token\\s+create|print\\s+token)\\b\',\n  \'op\\s+(?:read|inject|item\\s+get)\\b\',\n  \'security\\s+find-(?:generic|internet)-password\\b\',\n  \'doppler\\s+secrets\\b\',\n  \'heroku\\s+(?:auth:token|config)\\b\',\n  \'fly(?:ctl)?\\s+auth\\s+token\\b\',\n  \'sops\\s+(?:-d|--decrypt|decrypt)\\b\',\n  \'ansible-vault\\s+(?:view|decrypt)\\b\',\n  \'pass\\s+show\\b\',\n]\ntests.match = ["printenv", "sudo kubectl get secret db -o yaml", "cd x && gh auth token"]\ntests.no_match = ["env FOO=1 make", "kubectl get pods", "echo printenv"]\n';
